Section FXALL.
Context {fx : FPState}.

Definition STOPS2 : list Z := (0xd20e0 :: STOPS)%Z.

Definition rB2 := Eval vm_compute in sym_exec RSEGS FUEL true STOPS2 scr0 (SS 0xe1e50 srB0 [] knA 38) [].
Definition srB2 : list expr := Eval vm_compute in s_regs (fst (fst rB2)).

Tactic Notation "run_block" constr(scr) constr(NX) := run_block_gen_s FUEL STOPS scr NX false.
