Section Front.
  Context {AMB : Amb}.
  Variable sp0 : word.
  Variables a0s path : list byte.
  Variable envv : list (list byte).
  Variable tid : word.
  Variable rdraw : EntryDraw.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variable brk : word.
  Variable mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.
  Hypothesis Hva : valid_argv [a0s; path].
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
  Hypothesis ME : main_entry sp0 rdraw [a0s; path] envv a_uid a_hwcap tid regs0 mem0.

  Definition ENV (vals : list word) : env := Env (vals_ev vals) (blobs_ev (blobs0 a0s path)).

  Definition fds0 : list (word * FdEntry) :=
    [(Z_to_bv 64 0, FdChannel (Z_to_bv 64 0)); (Z_to_bv 64 1, FdChannel (Z_to_bv 64 1));
     (Z_to_bv 64 2, FdChannel (Z_to_bv 64 2))].
  Definition model0 : Model :=
    with_tid tid (init_model (segments_reserved RSEGS) brk mbase sp0 LIM (mkProcInputC [a0s; path] envv fs0 stdin0)).
  Definition model1 : Model := with_fds (fd_insert fds0 (Z_to_bv 64 3) (FdFile path (Z_to_bv 64 0))) model0.

  Definition model1d : Model := with_fds (fd_insert fds0 (Z_to_bv 64 3) FdDir) model0.

  Lemma m0_fds : m_fds model0 = fds0.
Proof.
ltac2:(KReplay.run1 (kr_t_S1RFront ()) ["FXALL"; "Front"] "p;1p;2g002cj10Tg00<Lj15Tg00<jj12Tg00=Mj21Tg00=mj14Tg006[j23Tg007S#0#0#0#0#0#0#5#2g00>M'1#4g00?E'3o"). Qed.
  Lemma alloc_fd_fds0 : alloc_fd fds0 = Z_to_bv 64 3.
Proof.
ltac2:(KReplay.run1 (kr_t_S1RFront ()) ["FXALL"; "Front"] "p;1p;2p;3g002cj10Tg00<Lj1:Tg00<jj12Tg003fj11Tg003Hj19Tg00@;j28Tg00@nj33Tg006[j24Tg00AQj15Tg00BHj26Tg005aj37Tg007SR0#0#0#0#0#0#0#:R1#2R2%10#9R01810531'4g00?E#51610572do"). Qed.
  Lemma fd_lookup_fds0_3 : fd_lookup fds0 (Z_to_bv 64 3) = None.
Proof.
ltac2:(KReplay.run1 (kr_t_S1RFront ()) ["FXALL"; "Front"] "p;1p;2g00Bnj12Tg00CPj11Tg006[j20Tg00>MR0#2%10'0o"). Qed.
