  Definition above_sp0 (M : word -> option byte) : Prop :=
    forall a : word, (bv_unsigned sp0 <= bv_unsigned a)%Z -> M a = mem0 a.

  Definition open_err_branch (KA : TSet) : Prop :=
    forall e vals R M,
      In e openat_errnos ->
      length vals = 39%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 38 = errno_ret e ->
      vals_ev vals 1 = p0 sp0 a0s path envv -> vals_ev vals 2 = p1 sp0 a0s path envv ->
      vals_ev vals 5 = tid ->
      regs_ok (ENV vals) (sr_upd srA (ridx 10) (EVar 38)) R -> know_ok RSEGS (ENV vals) M knA ->
      (forall x : word, (bv_unsigned sp0 <= bv_unsigned x)%Z -> M x = mem0 x) ->
      srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0xe1e50) M (seg_rom RSEGS)) model0) KA.

  Definition at_malloc1 (mo1 : Model) (K : TSet) : Prop :=
    forall vals R M,
      length vals = 38%nat -> vals_ev vals 0 = sp0 ->
      vals_ev vals 1 = p0 sp0 a0s path envv -> vals_ev vals 2 = p1 sp0 a0s path envv ->
      vals_ev vals 3 = auxvp sp0 a0s path envv -> vals_ev vals 4 = rnd rdraw -> vals_ev vals 5 = tid ->
      regs_ok (ENV vals) srB2 R -> know_ok RSEGS (ENV vals) M knA ->
      above_sp0 M -> mem_grows mem0 M ->
      (forall a : word, (bv_unsigned a < bv_unsigned sp0 - 8388608)%Z \/ (bv_unsigned sp0 <= bv_unsigned a)%Z -> M a = mem0 a) ->
      srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0xd20e0) M (seg_rom RSEGS)) mo1) K.

