    fs_lookup fs0 path = Some fdata -> path <> [] -> path <> dot_path -> (length path <= 4095)%nat ->
    open_err_branch KA -> at_malloc1 model1 K1 ->
    srealizes RSEGS (mkCfg (mkst regs0 (Z_to_bv 64 0x655e8) mem0 (seg_rom RSEGS)) model0) (t_alt2 KA K1).
